-- Marktplaats taxonomy seed (crawled 2026-08-21)
CREATE TABLE category (
  id            INTEGER PRIMARY KEY,
  parent_id     INTEGER NULL REFERENCES category(id),
  level         SMALLINT NOT NULL,
  slug          TEXT NOT NULL,
  full_name     TEXT NOT NULL,
  short_name    TEXT NULL,
  display_group TEXT NULL,
  listing_count INTEGER NULL,
  UNIQUE (parent_id, slug)
);
CREATE TABLE category_alias (alias_id INTEGER PRIMARY KEY, category_id INTEGER NOT NULL REFERENCES category(id));
CREATE TABLE facet_value (category_id INTEGER NOT NULL REFERENCES category(id), value_slug TEXT NOT NULL, value_id INTEGER NOT NULL, PRIMARY KEY (category_id, value_slug, value_id));

BEGIN;
COMMIT;
